// Extract owner/repo from GitHub URL
const repoUrl = $input.first().json.body.repoUrl || $input.first().json.repoUrl;
const branch = $input.first().json.body.branch || $input.first().json.branch || 'main';

let owner = '', repo = '';
try {
  const match = repoUrl.match(/github\.com\/([^/]+)\/([^/]+?)(?:\.git)?(?:\/|$)/);
  if (match) {
    owner = match[1];
    repo = match[2].replace('.git', '');
  }
} catch (e) {
  throw new Error('Invalid GitHub URL');
}

return { owner, repo, branch, repoUrl };

// Merge all GitHub data and build the AI prompt
const metadata = $input.all()[0];
const treeData = $input.all()[1];
const readmeData = $input.all()[2];
const packageData = $input.all()[3];

const repoInfo = metadata.json;
const treeInfo = treeData.json;

function decodeGithubContent(res) {
  if (!res || !res.json) return null;
  const j = res.json;
  if (typeof j === 'string') return j;
  if (j.content && j.encoding === 'base64') {
    try { return Buffer.from(j.content, 'base64').toString('utf-8'); } catch (e) { return null; }
  }
  return null;
}

const readmeContent = (decodeGithubContent(readmeData) || '').slice(0, 4000);
const packageJsonRaw = (decodeGithubContent(packageData) || '').slice(0, 2500);

// Convert GitHub tree to simplified file nodes
function buildFileTree(items) {
  const tree = [];

  items.forEach(item => {
    const parts = item.path.split('/');
    let current = tree;
    let currentPath = '';
    const isDir = item.type === 'tree';

    parts.forEach((part, i) => {
      currentPath = currentPath ? `${currentPath}/${part}` : part;
      const isLast = i === parts.length - 1;

      if (isLast) {
        const node = {
          name: part,
          path: currentPath,
          type: isDir ? 'dir' : 'file',
          size: item.size || 0
        };
        if (isDir) node.children = [];
        current.push(node);
      } else {
        let existing = current.find(n => n.name === part && n.type === 'dir');
        if (!existing) {
          existing = { name: part, path: currentPath, type: 'dir', children: [] };
          current.push(existing);
        } else if (!existing.children) {
          existing.children = [];
        }
        current = existing.children;
      }
    });
  });

  return tree;
}

const fileTree = treeInfo.tree ? buildFileTree(treeInfo.tree) : [];

// Detect languages from tree
const extensionMap = {};
treeInfo.tree?.forEach(item => {
  if (item.type === 'blob') {
    const ext = item.path.split('.').pop()?.toLowerCase();
    if (ext && ext.length < 10) {
      extensionMap[ext] = (extensionMap[ext] || 0) + (item.size || 1);
    }
  }
});

const extBreakdown = Object.entries(extensionMap)
  .sort((a, b) => b[1] - a[1])
  .map(([ext, bytes]) => `${ext}: ${bytes} bytes`)
  .join('\n');

const treeSnippet = JSON.stringify(fileTree, null, 2).slice(0, 6000);

// Build the AI prompt
const prompt = `You are a senior software engineer analyzing a GitHub repository.

Repository: ${repoInfo.full_name || repoInfo.name}
Description: ${repoInfo.description || 'N/A'}
Primary language (GitHub): ${repoInfo.language || 'Unknown'}
Stars: ${repoInfo.stargazers_count}
Forks: ${repoInfo.forks_count}
Open Issues: ${repoInfo.open_issues_count}
License: ${repoInfo.license?.spdx_id || 'N/A'}

README content:
${readmeContent || '(no README available)'}

package.json:
${packageJsonRaw || '(no package.json available)'}

File structure (${treeInfo.tree?.length || 0} files):
${treeSnippet}

File extension breakdown (by total bytes - this is the source of truth for the tech stack):
${extBreakdown || '(none)'}

Analyze this repository and return ONLY valid JSON with this exact structure (no markdown, no code blocks). STRICT RULES:
1. summary.purpose: 1-2 specific sentences about what this project actually does, based on the README and file structure. Never write generic text like "Repository analysis completed."
2. summary.architecture: describe the REAL structure you can see (top-level directories, entry files, how parts connect). Never write generic text like "Standard web application architecture."
3. summary.quality: assess code organization and best practices shown by the file structure (1-2 sentences).
4. techStack: derive ONLY from the file extension breakdown above. Never invent a language or framework whose extensions do not appear. Use category "language" for programming languages and "framework"/"tool" for frameworks and tools.
5. archDiagram: create a mermaid flowchart describing the REAL architecture from the top-level directories and key files. Use the syntax below but NEVER copy its content literally:
graph TD
    A[Component] --> B[Component]
6. stats: use EXACTLY the numbers provided above. Do not change, round, or invent them.

{
  "summary": {
    "purpose": "...",
    "architecture": "...",
    "quality": "...",
    "strengths": ["List 3-5 key strengths of this codebase"],
    "recommendations": ["List 2-4 suggestions for improvement"]
  },
  "techStack": [
    { "name": "Language/Framework", "category": "language|framework|tool|database", "icon": "single emoji", "percentage": 45 }
  ],
  "archDiagram": "graph TD\n    A[Component] --> B[Component]",
  "stats": {
    "stars": ${repoInfo.stargazers_count || 0},
    "forks": ${repoInfo.forks_count || 0},
    "openIssues": ${repoInfo.open_issues_count || 0},
    "license": "${repoInfo.license?.spdx_id || 'N/A'}",
    "contributors": 0,
    "lastCommit": "${repoInfo.updated_at || ''}"
  }
}`;

return {
  prompt,
  repoUrl: `https://github.com/${repoInfo.full_name || ''}`,
  branch: $json.branch || 'main',
  repoInfo,
  fileTree
};

// Parse AI response into structured JSON
const items = $input.all();
const agentOut = items[0].json;
const repoData = items[1]?.json || {};

let analysis = agentOut.output || agentOut.text || agentOut.message || agentOut.response || '{}';

// Try to extract JSON if wrapped in markdown code blocks
const jsonMatch = analysis.match(/\{[\s\S]*\}/);
if (jsonMatch) {
  analysis = jsonMatch[0];
}

const defaultStats = { stars: 0, forks: 0, openIssues: 0, license: 'N/A', contributors: 0, lastCommit: '' };

try {
  const parsed = typeof analysis === 'string' ? JSON.parse(analysis) : analysis;

  return {
    id: $json._webhookId || Date.now().toString(),
    repoUrl: repoData.repoUrl || '',
    branch: repoData.branch || 'main',
    analyzedAt: new Date().toISOString(),
    summary: parsed.summary || { purpose: '', architecture: '', quality: '', strengths: [], recommendations: [] },
    techStack: Array.isArray(parsed.techStack) ? parsed.techStack : [],
    fileTree: repoData.fileTree || [],
    archDiagram: typeof parsed.archDiagram === 'string' ? parsed.archDiagram : '',
    stats: { ...defaultStats, ...(parsed.stats || {}) }
  };
} catch (e) {
  return {
    id: Date.now().toString(),
    repoUrl: repoData.repoUrl || '',
    branch: repoData.branch || 'main',
    analyzedAt: new Date().toISOString(),
    summary: {
      purpose: 'Analysis completed but parsing failed.',
      architecture: '',
      quality: '',
      strengths: [],
      recommendations: []
    },
    techStack: [],
    fileTree: repoData.fileTree || [],
    archDiagram: '',
    stats: defaultStats,
    rawOutput: typeof analysis === 'string' ? analysis.slice(0, 2000) : JSON.stringify(analysis).slice(0, 2000)
  };
}
